<?php require_once __DIR__ . '/../cdn.php'; \SimpleCdn\Cdn::enable([]); $nodesFile = __DIR__ . '/../nodes.json'; $cdnNodes = []; if (is_file($nodesFile)) { $content = @file_get_contents($nodesFile); if ($content !== false) { $decoded = @json_decode($content, true); if (is_array($decoded)) { $cdnNodes = $decoded; } } } $purgeResult = null; if (session_status() === PHP_SESSION_NONE) { session_start(); } if (!empty($_SESSION['purge_result'])) { $purgeResult = $_SESSION['purge_result']; unset($_SESSION['purge_result']); } $deleted = 0; $message = ''; $messageType = 'info'; if ($_SERVER['REQUEST_METHOD'] === 'POST' && isset($_POST['action'])) { if ($_POST['action'] === 'clear_local') { $deleted = \SimpleCdn\Cdn::clearCache(); $message = '已删除 ' . number_format($deleted) . ' 个主站缓存文件'; $messageType = 'success'; } elseif ($_POST['action'] === 'purge_all') { $token = \SimpleCdn\Cdn::getPurgeToken(); header('Location: action.php?do=purge_all'); exit; } } ?> <!DOCTYPE html> <html lang="zh-CN"> <head> <meta charset="UTF-8"> <meta name="viewport" content="width=device-width, initial-scale=1.0"> <title>Simple CDN 后台 - 清缓存</title> <style> * { box-sizing: border-box; } body { font-family: system-ui, -apple-system, Segoe UI, Microsoft YaHei, sans-serif; background: #f5f7fa; color: #111; margin: 0; } .topbar { background: #fff; border-bottom: 1px solid #e2e8f0; padding: 12px 24px; display: flex; align-items: center; gap: 16px; } .topbar h1 { font-size: 16px; margin: 0; color: #0f172a; } .topbar a { color: #2563eb; text-decoration: none; font-size: 13px; } .topbar a:hover { text-decoration: underline; } .topbar .spacer { flex: 1; } .container { max-width: 1100px; margin: 32px auto; padding: 0 20px; } .card { background: #fff; border: 1px solid #e2e8f0; border-radius: 10px; padding: 24px; margin-bottom: 20px; } h2 { font-size: 18px; margin: 0 0 16px; color: #0f172a; } .msg { padding: 12px 16px; border-radius: 6px; margin-bottom: 16px; font-size: 14px; } .msg.ok { background: #dcfce7; color: #166534; border: 1px solid #86efac; } .msg.warn { background: #fef3c7; color: #92400e; border: 1px solid #fde68a; } .msg.info { background: #dbeafe; color: #1e40af; border: 1px solid #bfdbfe; } .btn { display: inline-block; padding: 10px 18px; border: none; border-radius: 6px; font-size: 14px; cursor: pointer; text-decoration: none; } .btn:hover { opacity: 0.9; } .btn-danger { background: #dc2626; color: #fff; } .btn-danger:hover { background: #b91c1c; } .btn-primary { background: #2563eb; color: #fff; } .btn-primary:hover { background: #1d4ed8; } .btn-secondary { background: #f1f5f9; color: #334155; } .btn-secondary:hover { background: #e2e8f0; } .btn-group { display: flex; gap: 12px; flex-wrap: wrap; margin-bottom: 16px; } .label { display: block; font-size: 13px; color: #64748b; margin-bottom: 6px; } .note { font-size: 13px; color: #64748b; margin-top: 16px; } .table { width: 100%; border-collapse: collapse; margin-top: 12px; } .table th { text-align: left; padding: 10px 12px; font-size: 13px; color: #64748b; border-bottom: 1px solid #f1f5f9; background: #fafbfc; } .table td { padding: 10px 12px; border-bottom: 1px solid #f1f5f9; font-size: 14px; } .table tr:hover { background: #f8fafc; } .badge { display: inline-block; padding: 2px 8px; border-radius: 10px; font-size: 11px; font-weight: 700; } .badge-success { background: #dcfce7; color: #166534; } .badge-fail { background: #fee2e2; color: #991b1b; } .badge-skip { background: #f1f5f9; color: #64748b; } .muted { color: #64748b; font-size: 13px; } .empty { color: #94a3b8; font-style: italic; } .token-box { background: #f8fafc; border: 1px solid #e2e8f0; border-radius: 6px; padding: 12px 16px; margin-bottom: 16px; font-family: ui-monospace, SFMono-Regular, Consolas, monospace; font-size: 13px; } .code { font-family: ui-monospace, SFMono-Regular, Consolas, monospace; font-size: 12px; background: #f1f5f9; padding: 2px 6px; border-radius: 4px; } </style> </head> <body> <div class="topbar"> <h1>清缓存</h1> <div class="spacer"></div> <a href="index.php" class="btn-secondary">← 返回仪表盘</a> </div> <div class="container"> <?php if ($message): ?> <div class="msg <?php echo $messageType === 'success' ? 'ok' : ($messageType === 'error' ? 'error' : 'info'); ?>"><?php echo htmlspecialchars($message); ?></div> <?php endif; ?> <?php if ($purgeResult): ?> <div class="msg ok"> <strong>一键清理完成</strong><br> 主站已删除 <strong><?php echo number_format($purgeResult['deleted']); ?></strong> 个缓存文件，<br> 节点通知：<span class="badge-success"><?php echo number_format($purgeResult['notified']); ?></span> 个成功， <span class="badge-fail"><?php echo number_format($purgeResult['failed']); ?></span> 个失败。 </div> <?php endif; ?> <div class="card"> <h2>1. 一键清理缓存</h2> <div class="btn-group"> <form method="POST" action="" onsubmit="return confirm('确定要清空主站所有 CDN 缓存吗？清空后首次访问将重新回源。');" style="margin:0;"> <button type="submit" name="action" value="clear_local" class="btn btn-danger">清理主站缓存</button> </form> <form method="POST" action="" onsubmit="return confirm('确定要清理所有节点的缓存吗？主站和全部启用的节点都会被清理。');" style="margin:0;"> <button type="submit" name="action" value="purge_all" class="btn btn-primary">清理所有节点缓存</button> </form> <a href="purge_logs.php" class="btn btn-secondary">查看清理日志</a> </div> <div class="note"> <strong>清理主站缓存</strong>：仅删除本站 <code>runtime-cache/</code> 目录下的所有 <code>.cache</code> 文件。<br> <strong>清理所有节点缓存</strong>：先清理主站，然后通过 <code>purge</code> 接口通知每个启用的 CDN 节点也清理本地缓存。<br> 清理后，首次访问时 CDN 将重新回源并重新缓存。 </div> </div> <?php if (!empty($cdnNodes)): ?> <div class="card"> <h2>2. 节点列表（共 <?php echo count($cdnNodes); ?> 个）</h2> <table class="table"> <thead> <tr> <th style="width:14%;">ID</th> <th style="width:18%;">名称</th> <th style="width:22%;">域名</th> <th style="width:16%;">状态</th> <th style="width:14%;">权重</th> <th style="width:16%;">操作</th> </tr> </thead> <tbody> <?php foreach ($cdnNodes as $i => $node): ?> <tr> <td><?php echo htmlspecialchars($node['id'] ?? ''); ?></td> <td><?php echo htmlspecialchars($node['name'] ?? ''); ?></td> <td><?php echo htmlspecialchars($node['domain'] ?? ''); ?></td> <td> <span class="badge <?php echo (isset($node['enabled']) && $node['enabled'] === true) ? 'badge-success' : 'badge-fail'; ?>"> <?php echo (isset($node['enabled']) && $node['enabled'] === true) ? '启用' : '禁用'; ?> </span> </td> <td><?php echo (int) ($node['weight'] ?? 0); ?></td> <td> <?php if (isset($node['enabled']) && $node['enabled'] === true): ?> <a href="action.php?do=toggle_node&index=<?php echo $i; ?>&enable=0" class="btn btn-secondary btn-sm" style="padding:4px 8px;font-size:12px;" onclick="return confirm('确定禁用此节点吗？');">禁用</a> <?php else: ?> <a href="action.php?do=toggle_node&index=<?php echo $i; ?>&enable=1" class="btn btn-secondary btn-sm" style="padding:4px 8px;font-size:12px;" onclick="return confirm('确定启用此节点吗？');">启用</a> <?php endif; ?> <a href="nodes.php?edit=<?php echo $i; ?>" class="btn btn-secondary btn-sm" style="padding:4px 8px;font-size:12px;">编辑</a> </td> </tr> <?php endforeach; ?> </tbody> </table> <p class="note">只有<strong>启用</strong>的节点会在一键清理时被通知。管理节点请前往 <a href="nodes.php" class="btn-secondary btn-sm">多节点管理</a>。</p> </div> <?php endif; ?> <div class="card"> <h2>3. HTTP Purge 接口（外部调用）</h2> <p>可通过 HTTP 请求触发缓存清理，适合与发布系统、CMS 等集成：</p> <div class="token-box"> <strong>GET</strong> <span class="code">{主站域名}/?purge=1&token={purge_token}&all_nodes=1</span> </div> <table class="table"> <thead> <tr><th style="width:20%;">参数</th><th>说明</th></tr> </thead> <tbody> <tr><td><code>purge</code></td><td>固定值 <code>1</code> 或 <code>true</code>，表示触发清理</td></tr> <tr><td><code>token</code></td><td>清理密钥，需与配置文件中的 <code>purge_token</code> 一致</td></tr> <tr><td><code>all_nodes</code></td><td>可选，<code>1</code> 表示清理完主站后同时通知所有节点也清理，<code>0</code> 或不传表示仅清理主站</td></tr> </tbody> </table> <div class="token-box"> <strong>示例</strong>：<br> <span class="code">curl "https://cdn.your-site.com/?purge=1&token=abc123&all_nodes=1"</span> </div> <div class="note"> <strong>安全提示</strong>：请在配置文件中设置 <code>purge_token</code> 为强随机字符串，防止未授权调用清理接口。<br> 若 <code>purge_token</code> 为空，远程 purge 接口将被禁用，仅后台可操作。 </div> </div> </div> </body> </html>;